"""Build an offline media selector only after all three official datasets validate."""
import argparse,html,json
from pathlib import Path
NAMES={'g1d':'宇树 G1-D','openarm':'OpenArm','so101':'SO101'}
CONDITIONS=['基准','暖光','冷光','布局与视角','材质','背景替换']
p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--date',default='20261021');a=p.parse_args();prefix='../../runs/multirobot-v3/';cards=[];total=0
for robot,label in NAMES.items():
 validation=json.loads((a.root/'datasets'/robot/'validation.json').read_text());assert validation['episodes']==12 and validation['all_numeric_rows_exact'];total+=validation['frames']
 for index in range(12):
  folder=a.root/'production'/robot/f'episode-{index:02d}';info=json.loads((folder/'verification.json').read_text());media=json.loads((folder/'media-verification.json').read_text());assert media['frames']==info['frames'];base=prefix+f'production/{robot}/episode-{index:02d}/';sorting=len(info['checks'])==3;task='RGB 方块排序' if sorting else '抓取方块';domain=CONDITIONS[info['condition']];mm=max(c['error_xy_m'] for c in info['checks'])*1000
  cards.append(f'''<article class="card" data-robot="{robot}" data-task="{'sort' if sorting else 'pick'}" data-domain="{info['condition']}"><video controls preload="none" poster="{base}poster-grasp.png"><source src="{base}overview.mp4" type="video/mp4"></video><div class="content"><div class="eyebrow">{label} <span>{domain}</span></div><h2>{task}</h2><p>{info['frames']/30:.1f} 秒 · 1080p / 30 fps · 落点误差 ≤ {mm:.1f} mm</p><nav><a href="{base}overview.mp4" download="{robot}-{'rgb-sort' if sorting else 'pick'}-domain-{info['condition']}.mp4">下载视频</a><a href="{base}poster-grasp.png" target="_blank">夹持图</a><a href="{base}poster-final.png" target="_blank">结果图</a></nav></div></article>''')
for robot,label in NAMES.items():
 for task,tasklabel in [('pick','抓取方块'),('sort','RGB 方块排序')]:
  stem=prefix+f'presentation/{robot}-{task}-domain-grid'
  if not (a.root/'presentation'/f'{robot}-{task}-domain-grid.mp4').exists():continue
  cards.insert(0,f'<article class="card" data-robot="{robot}" data-task="{task}" data-domain=""><video controls preload="none" poster="{stem}.png"><source src="{stem}.mp4" type="video/mp4"></video><div class="content"><div class="eyebrow">{label}<span>六条件对照</span></div><h2>{tasklabel} · 域随机化</h2><p>六条独立轨迹并排展示，便于选择 PPT 素材。</p><nav><a href="{stem}.mp4" download="{robot}-{task}-domains.mp4">下载对照视频</a></nav></div></article>')
heroes=[]
for robot,label in NAMES.items():
 image=prefix+f'presentation/{robot}-full-4k.png'
 if (a.root/'presentation'/f'{robot}-full-4k.png').exists():heroes.append(f'<article class="card" data-robot="{robot}" data-task="" data-domain=""><a href="{image}" target="_blank"><img src="{image}" alt="{label} 4K 全景" loading="lazy"></a><div class="content"><div class="eyebrow">{label}<span>3840 × 2160</span></div><h2>本体全景 · 路径追踪</h2><nav><a href="{image}" download="{robot}-full-4k.png">下载 4K 图</a></nav></div></article>')
cards=heroes+cards
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>三种机器人 · 高清仿真素材选择</title><style>
:root{color-scheme:dark;font-family:Inter,"Noto Sans CJK SC",system-ui,sans-serif;color:#e9eef5;background:#0d1118}*{box-sizing:border-box}body{margin:0}main{max-width:1480px;margin:auto;padding:56px 32px}header{margin-bottom:32px}.kicker{color:#79b8cf;letter-spacing:.15em;font-size:12px}h1{font-size:clamp(28px,4vw,52px);font-weight:650;letter-spacing:-.04em;margin:12px 0 16px}header p{max-width:850px;color:#a7b4c3;line-height:1.8}.stats{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}.stats span{border:1px solid #2c3a49;border-radius:30px;padding:8px 14px;font-size:13px}.filters{display:flex;gap:12px;flex-wrap:wrap;padding:20px 0 28px;position:sticky;top:0;background:#0d1118ed;z-index:2;backdrop-filter:blur(12px)}select{font:inherit;background:#18212c;color:#e9eef5;border:1px solid #344555;border-radius:8px;padding:11px 36px 11px 12px}.count{align-self:center;color:#8fa1b4;font-size:14px;margin-left:auto}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.card{border:1px solid #263441;border-radius:13px;overflow:hidden;background:#141c26}.card video,.card img{display:block;width:100%;aspect-ratio:16/9;object-fit:cover;background:#06090d}.content{padding:20px 22px}.eyebrow{font-size:13px;color:#8eb6c8}.eyebrow span{float:right;background:#243340;color:#afcad8;padding:4px 9px;border-radius:4px;font-size:12px}h2{font-size:21px;margin:12px 0 8px}.content p{color:#94a3b4;font-size:13px}.content nav{display:flex;gap:20px;margin-top:20px}a{color:#92d6e8;text-decoration:none}a:hover{text-decoration:underline}.content nav a{font-size:13px}footer{color:#8294a6;line-height:1.9;font-size:13px;margin-top:38px;border-top:1px solid #263441;padding-top:24px}article[hidden]{display:none}@media(max-width:850px){main{padding:28px 18px}.grid{grid-template-columns:1fr}.count{margin-left:0}}
</style><main><header><div class="kicker">WORLD SIMREADY HOME MINI · SCENE 000430</div><h1>三种机器人，两类任务。</h1><p>使用宇树 G1-D 原生 Dex3 手、OpenArm 原生夹爪、SO101 原生夹爪，在 mini 室内场景中抓取方块、按 RGB 次序排列。选择机器人、任务与随机化条件，直接预览和下载面试展示素材。</p><div class="stats"><span>36 条演示</span><span>1920 × 1080</span><span>原生 30 Hz</span><span>LeRobot v3.0 · 三套独立数据</span><span>FRAMES_PLACEHOLDER 帧</span></div></header><div class="filters"><select id="robot"><option value="">全部机器人</option><option value="g1d">宇树 G1-D</option><option value="openarm">OpenArm</option><option value="so101">SO101</option></select><select id="task"><option value="">全部任务</option><option value="pick">抓取方块</option><option value="sort">RGB 方块排序</option></select><select id="domain"><option value="">全部条件</option>DOMAIN_OPTIONS</select><span class="count" id="count"></span></div><section class="grid">CARDS_PLACEHOLDER</section><footer>这些是有真实接触动力学、由脚本控制的仿真演示，并非实拍或训练后策略测试。原始关节状态与动作已逐帧回放，三套 LeRobot 数据已通过官方读取器校验。<br>图像保留 mini 场景的桌面、地板与室内材质；背景替换条件使用三维背景板。<br><a href="autodata-multirobot-v3-20261021.md">数据结构、验收指标与适用范围</a></footer></main><script>
const controls=[document.querySelector('#robot'),document.querySelector('#task'),document.querySelector('#domain')],keys=['robot','task','domain'];function filter(){let shown=0;document.querySelectorAll('.card').forEach(card=>{card.hidden=controls.some((c,i)=>c.value&&card.dataset[keys[i]]!==c.value);if(!card.hidden)shown++});document.querySelector('#count').textContent=`显示 ${shown} 个素材`}controls.forEach(c=>c.addEventListener('change',filter));filter();
</script></html>'''
page=page.replace('autodata-multirobot-v3-20261021.md',f'autodata-multirobot-v3-{a.date}.md')
page=page.replace('CARDS_PLACEHOLDER','\n'.join(cards)).replace('FRAMES_PLACEHOLDER',f'{total:,}').replace('DOMAIN_OPTIONS',''.join(f'<option value="{i}">{label}</option>' for i,label in enumerate(CONDITIONS)));a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(page);print(a.output)
